interface Pricing12 {double fee(int minutes,boolean peak);} class CarPrice12 implements Pricing12 {public double fee(int m,boolean p){return ((m+59)/60)*30.0;}} class VanPrice12 implements Pricing12 {public double fee(int m,boolean p){return ((m+59)/60)*30.0*(p?2:1);}} class EBikePrice12 implements Pricing12 {public double fee(int m,boolean p){return 25.0;}} public class Task12Demo {public static void main(String[]x){int[] capacities={10,12,8,15,9};System.out.println("floors=5, capacities="+java.util.Arrays.toString(capacities));System.out.println("E-bike flat fee=Rs "+new EBikePrice12().fee(90,false));System.out.println("Delivery van off-peak=Rs "+new VanPrice12().fee(120,false));System.out.println("Delivery van peak=Rs "+new VanPrice12().fee(120,true));System.out.println("Car=Rs "+new CarPrice12().fee(120,false));System.out.println("Decision: MODIFY using jagged capacity array and separate pricing strategies.");}}